import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Ex08LruEviction {

    // 缓存容量受限时的淘汰策略：LRU 用「访问顺序」的 LinkedHashMap 即可
    static class LruCache {
        final int capacity;
        final List<String> evicted = new ArrayList<String>();
        final LinkedHashMap<String, Integer> map;

        LruCache(int capacity) {
            this.capacity = capacity;
            this.map = new LinkedHashMap<String, Integer>(capacity, 0.75f, true) {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, Integer> eldest) {
                    if (size() > LruCache.this.capacity) {
                        evicted.add(eldest.getKey());
                        return true;
                    }
                    return false;
                }
            };
        }

        void put(String key, int value) {
            map.put(key, value);
        }

        Integer get(String key) {
            return map.get(key);
        }

        List<String> keys() {
            return new ArrayList<String>(map.keySet());
        }
    }

    public static void main(String[] args) {
        LruCache cache = new LruCache(3);
        cache.put("a", 1);
        cache.put("b", 2);
        cache.put("c", 3);
        System.out.println("capacity         : " + cache.capacity);
        System.out.println("keys after a,b,c : " + cache.keys());

        cache.put("d", 4);
        System.out.println("keys after d     : " + cache.keys());

        cache.get("b");
        System.out.println("keys after get(b): " + cache.keys());

        cache.put("e", 5);
        System.out.println("keys after e     : " + cache.keys());
        System.out.println("evicted order    : " + cache.evicted);
        System.out.println("final keys       : " + cache.keys());
        System.out.println("size bounded     : " + (cache.keys().size() == cache.capacity));
    }
}
